import{_ as p,o as a,c as o,a0 as s}from"./chunks/framework.DqMqoJl9.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Object/Object.md","filePath":"jsApi/Object/Object.md","lastUpdated":1791573371000}'),t={name:"jsApi/Object/Object.md"};function n(c,e,l,r,d,i){return a(),o("div",null,[...e[0]||(e[0]=[s(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Object" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Object" target="_blank">en</a></p><p>Object</p><p>Object 构造函数创建一个对象包装器。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 对象初始化器（Object initialiser）或对象字面量（literal）</span></span>
<span class="line"><span style="color:#24292E;">{ [ nameValuePair1[, nameValuePair2[, </span><span style="color:#D73A49;">...</span><span style="color:#24292E;">nameValuePairN] ] ] }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 以构造函数形式来调用</span></span>
<span class="line"><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> Object</span><span style="color:#24292E;">([value])</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li><code>nameValuePair1, nameValuePair2, ... nameValuePairN</code> 成对的名称（字符串）与值（任何值），其中名称通过冒号与值分隔。</li><li><code>value</code> 任何值</li></ul><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>对象构造函数为给定值创建一个对象包装器。。如果给定值是 null or undefined，将会创建并返回一个空对象，否则，将返回一个与给 定值对应类型的对象。</p><p>当以非构造函数形式被调用时，Object 等同于 new Object()。</p><p>可查看 对象初始化/字面量语法。</p><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2><p><code>Object.length</code></p><p>值为1。</p><p><code>Object.prototype</code></p><p>可以为所有 Object 类型的对象添加属性。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>Object.assign()</code></p><p>通过复制一个或多个对象来创建一个新的对象。</p><p><code>Object.create()</code></p><p>指定原型对象和属性来创建一个新的对象。</p><p><code>Object.defineProperty()</code></p><p>给对象添加一个属性并指定该属性的配置。</p><p><code>Object.defineProperties()</code></p><p>给对象添加多个属性并分别指定它们的配置。</p><p><code>Object.entries() [草案]</code></p><p>返回一个数组，其是给定对象自身的 enumerable 属性键值对（[key, value]）。</p><p><code>Object.freeze()</code></p><p>冻结对象：使对象不可删除或修改它的属性。</p><p><code>Object.getOwnPropertyDescriptor()</code></p><p>返回对象指定的属性配置。</p><p><code>Object.getOwnPropertyNames()</code></p><p>返回一个数组，它包含了指定对象所有的可枚举或不可枚举的属性名。</p><p><code>Object.getOwnPropertySymbols()</code></p><p>返回一个数组，它包含了指定对象自身所有的符号属性。</p><p><code>Object.getPrototypeOf()</code></p><p>返回指定对象的原型对象。</p><p><code>Object.is()</code></p><p>判断两个值是否严格相等。（类似===运算符，但+0不等于-0，NaN等于自己）。</p><p><code>Object.isExtensible()</code></p><p>判断对象是否可扩展。</p><p><code>Object.isFrozen()</code></p><p>判断对象是否已经冻结。</p><p><code>Object.isSealed()</code></p><p>判断对象是否已经密封。</p><p><code>Object.keys()</code></p><p>返回一个数组，包含指定对象的所有自有可遍历属性的名称。</p><p><code>Object.preventExtensions()</code></p><p>阻止对象扩展。</p><p><code>Object.seal()</code></p><p>密封对象以防删除。</p><p><code>Object.setPrototypeOf()</code></p><p>设置对象的原型。</p><p><code>Object.values() [草案]</code></p><p>返回一个数组，其是给定对象自身的 enumerable 属性值。</p><h2 id="对象实例和对象原型对象" tabindex="-1">对象实例和对象原型对象 <a class="header-anchor" href="#对象实例和对象原型对象" aria-label="Permalink to &quot;对象实例和对象原型对象&quot;">​</a></h2><p>JavaScript语言的所有对象都是由Object衍生的对象；所有对象都继承了Object.prototype的方法和属性，尽管它们可能被覆盖。例如， 其它的构造器原型覆盖了constructor属性并提供了其自己的toString方法。原型对象的更改会传播给所有的对象，除非这些属性和方法 在原型链中被再次覆盖。</p><h3 id="属性-1" tabindex="-1">属性 <a class="header-anchor" href="#属性-1" aria-label="Permalink to &quot;属性&quot;">​</a></h3><p><code>Object.prototype.constructor</code></p><p>特定的函数，用于创建一个对象的原型。</p><p><code>Object.prototype.__proto__ [非标准]</code></p><p>指向当对象被实例化的时候，用作原型的对象。</p><p><code>Object.prototype.__noSuchMethod__ [非标准]</code></p><p>当未定义的对象成员被调用作方法的时候，允许定义并执行的函数。</p><p><code>Object.prototype.__count__ [已废弃]</code></p><p>用于直接返回用户定义的对象中可数的属性的数量。已被废除。</p><p><code>Object.prototype.__parent__ [已废弃]</code></p><p>用于指向对象的内容。已被废除。</p><h3 id="方法-1" tabindex="-1">方法 <a class="header-anchor" href="#方法-1" aria-label="Permalink to &quot;方法&quot;">​</a></h3><p><code>Object.prototype.__defineGetter__() [已废弃]</code></p><p>关联一个函数到一个属性。访问该函数时，执行该函数并返回其返回值。</p><p><code>Object.prototype.__defineSetter__() [已废弃]</code></p><p>关联一个函数到一个属性。设置该函数时，执行该修改属性的函数。</p><p><code>Object.prototype.__lookupGetter__() [已废弃]</code></p><p>返回使用 <strong>defineGetter</strong> 定义的方法函数 。</p><p><code>Object.prototype.__lookupSetter__() [已废弃]</code></p><p>返回使用 <strong>defineSetter</strong> 定义的方法函数。</p><p><code>Object.prototype.hasOwnProperty()</code></p><p>返回一个布尔值 ，表示某个对象是否含有指定的属性，而且此属性非原型链继承的。</p><p><code>Object.prototype.isPrototypeOf()</code></p><p>返回一个布尔值，表示指定的对象是否在本对象的原型链中。</p><p><code>Object.prototype.propertyIsEnumerable()</code></p><p>判断指定属性是否可枚举，内部属性设置参见 ECMAScript DontEnum attribute 。</p><p><code>Object.prototype.toSource() [非标准]</code></p><p>返回字符串表示此对象的源代码形式，可以使用此字符串生成一个新的相同的对象。</p><p><code>Object.prototype.toLocaleString()</code></p><p>直接调用 toString()方法。</p><p><code>Object.prototype.toString()</code></p><p>返回对象的字符串表示。</p><p><code>Object.prototype.unwatch() [非标准]</code></p><p>移除对象某个属性的监听。</p><p><code>Object.prototype.valueOf()</code></p><p>返回指定对象的原始值。</p><p><code>Object.prototype.watch() [非标准]</code></p><p>给对象的某个属性增加监听。</p><p><code>Object.prototype.eval() [已废弃]</code></p><p>在指定对象为上下文情况下执行javascript字符串代码，已经废弃。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>给定 undefined 和 null 类型使用 Object</p><p>下面的例子将一个空的 Object 对象存到 o 中：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> o </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Object</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> o </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Object</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">undefined</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> o </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Object</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">null</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="使用-object-生成布尔对象" tabindex="-1">使用 Object 生成布尔对象 <a class="header-anchor" href="#使用-object-生成布尔对象" aria-label="Permalink to &quot;使用 Object 生成布尔对象&quot;">​</a></h3><p>下面的例子将Boolean 对象存到 o 中：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 等价于 o = new Boolean(true);</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> o </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Object</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">true</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 等价于 o = new Boolean(false);</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> o </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Object</span><span style="color:#24292E;">(</span><span style="color:#6F42C1;">Boolean</span><span style="color:#24292E;">());</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,104)])])}const y=p(t,[["render",n]]);export{u as __pageData,y as default};
